import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter_agent_harness/flutter_agent_harness.dart';

import 'package:fa_ui/src/providers/add_provider_picker.dart';
import 'package:fa_ui/src/providers/connection.dart';
import 'package:fa_ui/src/providers/default_chat_model.dart';
import 'package:fa_ui/src/providers/provider_preset.dart';
import 'package:fa_ui/src/stores/provider_registry.dart';
import 'package:fa_ui/src/stores/session_keys_store.dart';
import 'package:fa_ui/src/strings/fa_ui_strings.dart';
import 'package:fa_ui/src/utils/page_presentation.dart';

/// A model entry in the [UnifiedModelPickerPage]: the provider that owns it,
/// the model id, and the display label.
final class _ModelEntry {
  _ModelEntry({
    required this.provider,
    required this.providerId,
    required this.baseUrl,
    required this.apiKey,
    required this.modelId,
    required this.contextWindow,
    required this.maxTokens,
    this.kind,
  });

  final String provider;
  final String? providerId;
  final String baseUrl;
  final String apiKey;
  final String modelId;
  final int contextWindow;
  final int maxTokens;

  /// The source entry's persisted identity ([CustomProvider.kind]) — wins
  /// over URL matching in the save path, mirroring the fetch hint.
  final String? kind;

  bool matches(String filter) {
    final lower = filter.toLowerCase();
    return provider.toLowerCase().contains(lower) ||
        modelId.toLowerCase().contains(lower);
  }
}

/// A CONNECTED endpoint provider gathered for the `/models` fetch: a saved
/// [CustomProvider] or a hosted preset (its display name + stable name).
typedef _FetchProvider = ({
  String name,
  String id,
  String baseUrl,
  String? kind,
});

/// A unified model picker that shows **all** models from **all** configured
/// providers in a single flat list, mirroring the CLI's `/model` command.
///
/// Features:
/// - Fetches `/models` from every saved [CustomProvider] in parallel.
/// - Search field at the top filters by provider name OR model id.
/// - Each row shows `provider / model-id` with a vision marker.
/// - On-device routes (WebLLM, Gemma, …) appear as separate tiles at the
///   bottom.
/// - An "Add provider" tile opens the preset picker.
///
/// Selecting a model builds a [FaChatModelConfig] with the right provider's
/// resolved key and runs [onApply]. Selecting an on-device route delegates
/// to its page builder.
class UnifiedModelPickerPage extends StatefulWidget {
  /// Creates the picker.
  const UnifiedModelPickerPage({
    super.key,
    required this.connection,
    required this.onApply,
    this.registry,
    this.modelsFetcher,
    this.onDeviceProviders = const [],
    this.providerKindLabels = const {},
    this.addProviderPage,
  });

  /// The active connection — its model is highlighted as "current".
  final FaChatConnection connection;

  /// Applies the chosen config as the main connection.
  final Future<void> Function(FaChatModelConfig config) onApply;

  /// The user-added providers.
  final ProviderRegistry? registry;

  /// `/models` fetch override (tests); production goes through the core
  /// [fetchModelsForEndpoint] dispatch directly.
  final ModelsEndpointFetcher? modelsFetcher;

  /// On-device provider routes (Gemma, WebLLM, …), appended to the list.
  final List<FaOnDeviceRoute> onDeviceProviders;

  /// Display labels for non-endpoint provider kinds (on-device backends).
  final Map<String, String> providerKindLabels;

  /// A host-provided widget builder for the "Add provider" page — the
  /// preset picker with the host's SSO/OAuth tiles. When null, the same
  /// [AddProviderPresetPickerPage] is built from this picker's registry
  /// (issue #975: every add-provider entry opens the ONE settings flow).
  final WidgetBuilder? addProviderPage;

  @override
  State<UnifiedModelPickerPage> createState() => _UnifiedModelPickerPageState();
}

class _UnifiedModelPickerPageState extends State<UnifiedModelPickerPage> {
  final _searchController = TextEditingController();
  final _searchFocus = FocusNode();

  /// All fetched model entries across every provider.
  List<_ModelEntry> _entries = const [];
  var _loading = true;
  String? _error;

  /// The provider kind for a picked model entry — matches the dispatch
  /// hint so the stream adapter gets the right wire shape. The source
  /// entry's persisted identity wins; Google endpoints need the Gemini
  /// adapter (inlineData, not image_url); DIAL and Copilot have their own
  /// dialects; Codex rides the codex wire.
  String _providerKindFor(String? kind, String baseUrl) {
    if (kind != null) return kind;
    final preset = ProviderPreset.fromBaseUrl(baseUrl);
    if (preset == ProviderPreset.dial) return 'dial';
    if (isCopilotBaseUrl(baseUrl)) return 'copilot';
    if (baseUrl.contains('generativelanguage.googleapis.com')) return 'google';
    if (isChatGptCodexEndpoint(baseUrl)) return 'chatgpt-codex';
    return 'openai-completions';
  }

  @override
  void initState() {
    super.initState();
    _searchController.addListener(() {
      if (mounted) setState(() {});
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _fetchAllModels();
    });
  }

  @override
  void dispose() {
    _searchController.dispose();
    _searchFocus.dispose();
    super.dispose();
  }

  Future<void> _fetchAllModels() async {
    final entries = <_ModelEntry>[];

    // Gather all CONNECTED endpoint providers: saved custom providers plus
    // hosted presets whose key resolves (hostedProviderConnected) — the
    // same set every other picker in the app shows. A custom provider on a
    // preset's endpoint covers the preset (never both).
    final providers = <_FetchProvider>[];
    _collectProviders(providers);

    if (providers.isEmpty) {
      // No saved providers — just show the active model.
      entries.add(_entryFromActive());
      if (mounted) setState(() => _loading = false);
      return;
    }

    // Fetch in parallel.
    final results = await Future.wait(providers.map(_fetchOne));

    for (final result in results) {
      entries.addAll(result);
    }

    // Always include the active model even if the fetch failed.
    _insertActiveEntry(entries);
    _publishEntries(entries);
  }

  /// Publishes the fetched entries (a no-op once unmounted).
  void _publishEntries(List<_ModelEntry> entries) {
    if (mounted) {
      setState(() {
        _entries = entries;
        _loading = false;
      });
    }
  }

  /// The saved entries plus the connected hosted presets into [providers].
  void _collectProviders(List<_FetchProvider> providers) {
    final registry = widget.registry;
    if (registry == null) return;
    for (final p in registry.providers) {
      providers.add((name: p.name, id: p.id, baseUrl: p.baseUrl, kind: p.kind));
    }
    _collectHostedPresets(providers);
  }

  /// The hosted presets that list right now (see [_hostedPresetListable]).
  void _collectHostedPresets(List<_FetchProvider> providers) {
    for (final preset in hostedProviderPresets) {
      if (!_hostedPresetListable(preset, providers)) continue;
      providers.add((
        name: preset.labelFor(context),
        id: preset.name,
        baseUrl: preset.baseUrl!,
        kind: null,
      ));
    }
  }

  /// Whether a hosted preset lists now: it has an endpoint, no saved
  /// custom provider already covers it (never both), and its key resolves
  /// ([hostedProviderConnected]).
  bool _hostedPresetListable(
    ProviderPreset preset,
    List<_FetchProvider> providers,
  ) =>
      preset.baseUrl != null &&
      !providers.any((p) => p.baseUrl == preset.baseUrl) &&
      hostedProviderConnected(preset);

  /// The active model entry prepended when no fetch result carries it
  /// (the fetch failed / the endpoint dropped it).
  void _insertActiveEntry(List<_ModelEntry> entries) {
    final activeModel = widget.connection.modelId;
    final activeBase = widget.connection.activeBaseUrl;
    if (entries.any(
      (e) => e.modelId == activeModel && e.baseUrl == activeBase,
    )) {
      return;
    }
    entries.insert(0, _entryFromActive());
  }

  _ModelEntry _entryFromActive() {
    final activeId = widget.connection.activeProviderId;
    final activeKind = widget.registry?.providers
        .where((p) => p.id == activeId)
        .firstOrNull
        ?.kind;
    return _ModelEntry(
      provider: _activeProviderLabel(),
      providerId: activeId,
      baseUrl: widget.connection.activeBaseUrl,
      apiKey: '',
      modelId: widget.connection.modelId,
      contextWindow: fallbackContextWindow,
      maxTokens: fallbackMaxTokens,
      kind: activeKind,
    );
  }

  String _activeProviderLabel() {
    final kindLabel = widget.providerKindLabels[widget.connection.providerKind];
    if (kindLabel != null) return kindLabel;
    final base = widget.connection.activeBaseUrl;
    final registry = widget.registry;
    if (registry != null) {
      final match = providerForBaseUrl(base, registry);
      if (match != null) {
        return match is CustomProvider ? match.name : match.toString();
      }
    }
    return providerHostOf(base);
  }

  Future<List<_ModelEntry>> _fetchOne(_FetchProvider provider) async {
    try {
      final key = _resolveFetchKey(provider);
      final info = await _fetchModels(provider, key);
      return _listedEntries(provider, key, info);
    } on Object {
      // Dead endpoint — try the saved model.
      return _deadEndpointEntries(provider);
    }
  }

  /// The fetch key for [provider]: the registry's session key first; when
  /// it does not resolve, the hosted preset's named key (env / secure
  /// store / saved keys); when that does not either, the saved entry's
  /// own resolution.
  String _resolveFetchKey(_FetchProvider provider) {
    var key = widget.registry?.keyFor(provider.id) ?? '';
    if (key.isEmpty) key = _hostedPresetKey(provider.id);
    if (key.isEmpty) key = _savedEntryKey(provider.id);
    return key;
  }

  /// The hosted preset whose id matches [id], or null.
  ProviderPreset? _hostedPresetFor(String id) =>
      hostedProviderPresets.where((p) => p.name == id).firstOrNull;

  /// The saved entry with [id], or null.
  CustomProvider? _savedProviderFor(String id) =>
      widget.registry?.providers.where((p) => p.id == id).firstOrNull;

  /// The hosted-preset key fallback: the preset's named key resolves
  /// through the host's key chain (env / secure store / saved keys).
  String _hostedPresetKey(String id) {
    final preset = _hostedPresetFor(id);
    if (preset == null) return '';
    return resolveProviderKey(
      preset,
      registry: widget.registry,
      keysStore: SessionKeysScope.maybeOf(context),
    );
  }

  /// The saved-entry key fallback: Copilot tokens live entry-scoped
  /// (`FA_KEY_COPILOT_<NAME>`) after a restart on platforms without a
  /// Keychain backend.
  String _savedEntryKey(String id) {
    final custom = _savedProviderFor(id);
    if (custom == null) return '';
    return resolveProviderKey(
      custom,
      registry: widget.registry,
      keysStore: SessionKeysScope.maybeOf(context),
    );
  }

  /// `/models` for [provider]: the host/test override wins; production
  /// goes through the core dispatch (DIAL deployments, the CodeMie
  /// marker, the bundled Codex catalog, and the Copilot token exchange
  /// all live in there), with the entry's persisted identity winning
  /// over URL matching.
  Future<ModelsEndpointInfo> _fetchModels(_FetchProvider provider, String key) {
    if (widget.modelsFetcher != null) {
      return widget.modelsFetcher!(provider.baseUrl, apiKey: key);
    }
    return fetchModelsForEndpoint(
      provider.baseUrl,
      apiKey: key,
      provider: modelsDispatchHintForEntry(provider.kind, provider.baseUrl),
    );
  }

  /// The endpoint's answer as picker entries: the listed ids, or the
  /// saved model when the endpoint lists nothing.
  List<_ModelEntry> _listedEntries(
    _FetchProvider provider,
    String key,
    ModelsEndpointInfo info,
  ) {
    final (ids, windows, caps) = info;
    if (ids.isEmpty) return _emptyListingEntries(provider, key);
    return [
      for (final id in ids) _listedModelEntry(provider, key, id, windows, caps),
    ];
  }

  /// One listed id as an entry ([windows]/[caps] per-model when reported,
  /// the shared fallback otherwise).
  _ModelEntry _listedModelEntry(
    _FetchProvider provider,
    String key,
    String id,
    Map<String, int> windows,
    Map<String, int> caps,
  ) => _ModelEntry(
    provider: provider.name,
    providerId: provider.id,
    baseUrl: provider.baseUrl,
    apiKey: key,
    modelId: id,
    contextWindow: windows[id] ?? fallbackContextWindow,
    maxTokens: caps[id] ?? fallbackMaxTokens,
    kind: provider.kind,
  );

  /// A fetch that answered but listed nothing: the provider's saved model
  /// stands in (with the resolved fetch key), or nothing at all.
  List<_ModelEntry> _emptyListingEntries(_FetchProvider provider, String key) {
    final savedModel = _savedModelOf(provider.id);
    if (savedModel == null || savedModel.isEmpty) return const [];
    return [
      _ModelEntry(
        provider: provider.name,
        providerId: provider.id,
        baseUrl: provider.baseUrl,
        apiKey: key,
        modelId: savedModel,
        contextWindow: fallbackContextWindow,
        maxTokens: fallbackMaxTokens,
      ),
    ];
  }

  /// A dead endpoint: the provider's saved model stands in (keyed by the
  /// registry's own session key — nothing resolved), or nothing at all.
  List<_ModelEntry> _deadEndpointEntries(_FetchProvider provider) {
    final savedModel = _savedModelOf(provider.id);
    if (savedModel == null || savedModel.isEmpty) return const [];
    return [
      _ModelEntry(
        provider: provider.name,
        providerId: provider.id,
        baseUrl: provider.baseUrl,
        apiKey: widget.registry?.keyFor(provider.id) ?? '',
        modelId: savedModel,
        contextWindow: fallbackContextWindow,
        maxTokens: fallbackMaxTokens,
        kind: provider.kind,
      ),
    ];
  }

  /// The saved entry's model id (the fetch-fallback model).
  String? _savedModelOf(String providerId) =>
      widget.registry?.providers.where((p) => p.id == providerId).first.modelId;

  String get _filter => _searchController.text.trim();

  List<_ModelEntry> get _filtered {
    if (_filter.isEmpty) return _entries;
    return _entries.where((e) => e.matches(_filter)).toList();
  }

  /// The manual escape's target: the typed id applied on the ACTIVE
  /// provider's endpoint, its key resolved through the registry like any
  /// listed entry's.
  _ModelEntry _manualEntry(String typedId) {
    final base = _entryFromActive();
    final registry = widget.registry;
    var key = '';
    if (registry != null) {
      final activeId = widget.connection.activeProviderId;
      if (activeId != null) {
        key = registry.keyFor(activeId) ?? '';
      } else {
        final match = providerForBaseUrl(base.baseUrl, registry);
        if (match is CustomProvider) key = registry.keyFor(match.id) ?? '';
      }
    }
    return _ModelEntry(
      provider: base.provider,
      providerId: base.providerId,
      baseUrl: base.baseUrl,
      apiKey: key,
      modelId: typedId,
      contextWindow: fallbackContextWindow,
      maxTokens: fallbackMaxTokens,
    );
  }

  Future<void> _selectModel(_ModelEntry entry) async {
    setState(() => _error = null);
    // The keyless-request guard (issue #329): a keyed entry whose key
    // does not resolve on this surface never reaches the host — the named
    // message replaces the raw provider 401 the user would otherwise
    // discover after the first turn.
    if (entry.apiKey.isEmpty) {
      final custom = widget.registry?.providers
          .where((p) => p.id == entry.providerId)
          .firstOrNull;
      if (custom != null &&
          isKeyMissingOnSurface(custom, registry: widget.registry)) {
        setState(
          () =>
              _error = FaUiStrings.of(context).missingKeyOnDevice(custom.name),
        );
        return;
      }
    }
    try {
      await widget.onApply(
        FaChatModelConfig(
          // DIAL deployments live on a dial adapter kind (URL/auth dialect);
          // Google endpoints use the Gemini adapter (inlineData, not
          // image_url); everything else is plain openai-completions.
          providerKind: _providerKindFor(entry.kind, entry.baseUrl),
          modelId: entry.modelId,
          baseUrl: entry.baseUrl,
          apiKey: entry.apiKey,
          contextWindow: entry.contextWindow,
          maxTokens: entry.maxTokens,
          supportsImages: modelIdSuggestsVision(entry.modelId),
          providerId: entry.providerId,
        ),
      );
      if (mounted) Navigator.of(context).pop();
    } catch (e) {
      if (mounted) setState(() => _error = e.toString());
    }
  }

  Future<void> _openOnDevice(FaOnDeviceRoute route) async {
    final ctx = context;
    final applied = await pushFaPage<bool>(
      ctx,
      route.pageBuilder(ctx, widget.onApply),
    );
    if (applied == true && mounted) Navigator.of(context).pop();
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final strings = FaUiStrings.of(context);
    final entries = _filtered;
    return Scaffold(
      appBar: AppBar(title: Text(strings.settingsPickModelTitle)),
      body: SafeArea(
        child: Column(
          children: [
            // Search field.
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 12, 16, 4),
              child: TextField(
                controller: _searchController,
                focusNode: _searchFocus,
                decoration: InputDecoration(
                  prefixIcon: const Icon(Icons.search, size: 20),
                  hintText: 'Filter models…',
                  isDense: true,
                  border: const OutlineInputBorder(),
                  suffixIcon: _filter.isNotEmpty
                      ? IconButton(
                          icon: const Icon(Icons.clear, size: 18),
                          onPressed: () {
                            _searchController.clear();
                            _searchFocus.requestFocus();
                          },
                        )
                      : null,
                ),
              ),
            ),
            // Model list.
            Expanded(
              child: _loading
                  ? const Center(child: CircularProgressIndicator())
                  : ListView(
                      padding: const EdgeInsets.symmetric(vertical: 4),
                      children: [
                        // The manual escape: the typed id is always
                        // applicable on the active provider's endpoint.
                        if (_filter.isNotEmpty &&
                            !_entries.any((e) => e.modelId == _filter))
                          ListTile(
                            leading: Icon(
                              Icons.edit_outlined,
                              size: 20,
                              color: theme.colorScheme.primary,
                            ),
                            title: Text(
                              strings.modelPickerUseManual(_filter),
                              overflow: TextOverflow.ellipsis,
                            ),
                            subtitle: Text(
                              _activeProviderLabel(),
                              overflow: TextOverflow.ellipsis,
                            ),
                            onTap: () => _selectModel(_manualEntry(_filter)),
                          ),
                        for (final entry in entries)
                          _modelTile(context, theme, entry),
                        // On-device routes.
                        for (final route in widget.onDeviceProviders)
                          ListTile(
                            leading: Icon(
                              Icons.memory_outlined,
                              color: theme.colorScheme.primary,
                            ),
                            title: Text(route.label),
                            trailing: Icon(
                              Icons.chevron_right,
                              size: 18,
                              color: theme.colorScheme.onSurfaceVariant,
                            ),
                            onTap: () => _openOnDevice(route),
                          ),
                        if (widget.registry != null) ...[
                          const Divider(),
                          // Add provider. Needs a registry to save into —
                          // hidden when the host embeds the picker without
                          // one (a null registry would silently discard
                          // the add).
                          ListTile(
                            leading: Icon(
                              Icons.add,
                              color: theme.colorScheme.primary,
                            ),
                            title: Text(strings.settingsAddProvider),
                            onTap: () async {
                              await pushAddProviderFlow(
                                context,
                                hostPage: widget.addProviderPage,
                                registry: widget.registry,
                                modelsFetcher: widget.modelsFetcher,
                                onDeviceRoutes: widget.onDeviceProviders,
                              );
                              if (mounted) _fetchAllModels();
                            },
                          ),
                        ],
                      ],
                    ),
            ),
            if (_error != null)
              Padding(
                padding: const EdgeInsets.all(16),
                child: Text(
                  _error!,
                  style: TextStyle(color: theme.colorScheme.error),
                ),
              ),
          ],
        ),
      ),
    );
  }

  Widget _modelTile(BuildContext context, ThemeData theme, _ModelEntry entry) {
    final isActive =
        entry.modelId == widget.connection.modelId &&
        entry.baseUrl == widget.connection.activeBaseUrl;
    return ListTile(
      leading: Icon(
        isActive ? Icons.check_circle : Icons.radio_button_unchecked,
        size: 20,
        color: isActive
            ? theme.colorScheme.primary
            : theme.colorScheme.onSurfaceVariant,
      ),
      title: RichText(
        maxLines: 1,
        overflow: TextOverflow.ellipsis,
        text: TextSpan(
          style: theme.textTheme.bodyMedium,
          children: [
            TextSpan(
              text: entry.provider,
              style: TextStyle(color: theme.colorScheme.onSurfaceVariant),
            ),
            TextSpan(
              text: ' / ',
              style: TextStyle(color: theme.colorScheme.outline),
            ),
            TextSpan(
              text: entry.modelId,
              style: TextStyle(
                fontWeight: isActive ? FontWeight.bold : FontWeight.normal,
              ),
            ),
          ],
        ),
      ),
      subtitle: Text(
        visionMarkerText(entry.modelId),
        style: theme.textTheme.bodySmall,
      ),
      onTap: () => _selectModel(entry),
    );
  }
}

/// The vision marker text for [modelId] (empty when the model does not
/// suggest vision input).
String visionMarkerText(String modelId) =>
    modelIdSuggestsVision(modelId) ? 'vision ✓' : '';

import 'package:audioplayers/audioplayers.dart' show AudioPlayer;
import 'package:fa_ui/fa_ui.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';

/// audioplayers' method channels (audioplayers_platform_interface 7.x):
/// one global, one shared per-player channel carrying the playerId, and
/// one event channel per player (`…/events/$playerId`).
const _playerChannel = MethodChannel('xyz.luan/audioplayers');
const _globalChannel = MethodChannel('xyz.luan/audioplayers.global');

const _kore = FaVoicePreset(
  id: 'Kore',
  trait: 'Firm',
  sampleUrl: 'https://example.invalid/samples/Kore.wav',
);

Widget _host({
  String? value = 'Kore',
  bool enabled = true,
  ValueChanged<String>? onChanged,
  List<FaVoicePreset> presets = const [_kore],
}) => MaterialApp(
  home: Scaffold(
    body: FaVoicePresetPicker(
      presets: presets,
      value: value,
      onChanged: onChanged ?? (_) {},
      enabled: enabled,
    ),
  ),
);

/// Installs mock handlers answering every audioplayers platform call; the
/// created player's id is captured so tests can emit platform events.
///
/// The handlers stay installed through teardown: the widget tree is
/// disposed after `addTearDown` callbacks run, and the picker's
/// `AudioPlayer.dispose()` would throw against a missing plugin there.
void _stubAudioplayers(WidgetTester tester, void Function(String) onCreated) {
  tester.binding.defaultBinaryMessenger.setMockMethodCallHandler(
    _globalChannel,
    (_) async => null,
  );
  tester.binding.defaultBinaryMessenger.setMockMethodCallHandler(
    _playerChannel,
    (call) async {
      if (call.method == 'create') {
        onCreated((call.arguments as Map)['playerId'] as String);
      }
      return null;
    },
  );
}

/// Delivers a native audio event to the player's event channel.
void _emitAudioEvent(
  WidgetTester tester,
  String playerId,
  Map<String, Object?> event,
) {
  tester.binding.defaultBinaryMessenger.handlePlatformMessage(
    'xyz.luan/audioplayers/events/$playerId',
    const StandardMethodCodec().encodeSuccessEnvelope(event),
    (_) {},
  );
}

void main() {
  group('FaVoicePresetPicker', () {
    testWidgets('shows the preview button only when the preset has a sample', (
      tester,
    ) async {
      await tester.pumpWidget(_host());
      expect(find.byIcon(Icons.play_arrow), findsOneWidget);

      await tester.pumpWidget(
        _host(
          value: 'af_heart',
          presets: const [FaVoicePreset(id: 'af_heart')],
        ),
      );
      expect(find.byIcon(Icons.play_arrow), findsNothing);
    });

    testWidgets(
      'preview play/stop cycles through loading, playing, and reset',
      (tester) async {
        // One test drives the whole preview cycle: audioplayers' global
        // scope caches its init completer per process, so a second
        // testWidgets creating an AudioPlayer would await a completer
        // completed in the previous test's (dead) fake-async zone.
        //
        // The backend never prepares on the first play: the preparation
        // timeout (30s real, 1ms here so fake time fires it) fails over
        // silently; later plays get an explicit `prepared` event, then a
        // `complete` event resets the button.
        AudioPlayer.preparationTimeout = const Duration(milliseconds: 1);
        addTearDown(
          () => AudioPlayer.preparationTimeout = const Duration(seconds: 30),
        );
        var playerId = '';
        _stubAudioplayers(tester, (id) => playerId = id);
        await tester.pumpWidget(_host());
        await tester.pump();

        // Play without a prepared event — fails over to idle.
        await tester.tap(find.byIcon(Icons.play_arrow));
        await tester.pump();
        expect(find.byType(CircularProgressIndicator), findsOneWidget);

        await tester.pump(const Duration(seconds: 1));
        await tester.pump();
        expect(find.byIcon(Icons.play_arrow), findsOneWidget);
        expect(find.byType(CircularProgressIndicator), findsNothing);

        // Play again — this time the platform prepares the clip.
        await tester.tap(find.byIcon(Icons.play_arrow));
        await tester.pump();
        _emitAudioEvent(tester, playerId, {
          'event': 'audio.onPrepared',
          'value': true,
        });
        await tester.pump();
        expect(find.byIcon(Icons.stop), findsOneWidget);
        expect(find.byIcon(Icons.play_arrow), findsNothing);

        await tester.tap(find.byIcon(Icons.stop));
        await tester.pump();
        expect(find.byIcon(Icons.play_arrow), findsOneWidget);
        expect(find.byIcon(Icons.stop), findsNothing);

        // A third play, reset by native playback completion.
        await tester.tap(find.byIcon(Icons.play_arrow));
        await tester.pump();
        _emitAudioEvent(tester, playerId, {
          'event': 'audio.onPrepared',
          'value': true,
        });
        await tester.pump();
        expect(find.byIcon(Icons.stop), findsOneWidget);

        _emitAudioEvent(tester, playerId, {'event': 'audio.onComplete'});
        await tester.pump();
        expect(find.byIcon(Icons.play_arrow), findsOneWidget);
        expect(find.byIcon(Icons.stop), findsNothing);
      },
    );

    testWidgets('a saved voice unknown to the presets stays selectable', (
      tester,
    ) async {
      await tester.pumpWidget(_host(value: 'my-custom-voice'));
      expect(find.text('my-custom-voice'), findsOneWidget);
      // Unknown voices publish no sample — no preview button.
      expect(find.byIcon(Icons.play_arrow), findsNothing);
    });

    testWidgets('a disabled picker renders the dropdown without a handler', (
      tester,
    ) async {
      await tester.pumpWidget(_host(enabled: false));
      final dropdown = tester.widget<DropdownButtonFormField<String>>(
        find.byType(DropdownButtonFormField<String>),
      );
      expect(dropdown.onChanged, isNull);
    });
  });

  group('faVoicePresetsFor', () {
    test('matches Gemini TTS by model id (gemini + tts)', () {
      final presets = faVoicePresetsFor(
        modelId: 'gemini-2.5-flash-preview-tts',
      );
      expect(presets, hasLength(30));
      expect(presets.first.id, 'Zephyr');
      expect(presets.first.trait, 'Bright');
      expect(
        presets.first.sampleUrl,
        'https://www.gstatic.com/aistudio/voices/samples/Zephyr.wav',
      );
      expect(presets.last.id, 'Sulafat');
      expect(presets.last.trait, 'Warm');
    });

    test('matches Gemini by base URL regardless of the model id', () {
      final presets = faVoicePresetsFor(
        baseUrl: 'https://generativelanguage.googleapis.com/v1beta',
        modelId: 'some-model',
      );
      expect(presets, hasLength(30));
    });

    test('matches Kokoro by model id (no sample urls)', () {
      final presets = faVoicePresetsFor(modelId: 'kokoro-82m');
      expect(presets.map((preset) => preset.id), [
        'af_heart',
        'af_bella',
        'af_nicole',
        'af_sarah',
        'af_sky',
        'am_adam',
        'am_michael',
        'am_onyx',
        'bf_emma',
        'bf_isabella',
        'bm_george',
        'bm_lewis',
      ]);
      expect(presets.every((preset) => preset.sampleUrl == null), isTrue);
    });

    test('matches OpenAI-compatible TTS by the tts marker', () {
      final presets = faVoicePresetsFor(modelId: 'tts-1');
      expect(presets.map((preset) => preset.id), [
        'alloy',
        'ash',
        'coral',
        'echo',
        'fable',
        'nova',
        'onyx',
        'sage',
        'shimmer',
      ]);
      expect(presets.every((preset) => preset.sampleUrl == null), isTrue);
    });

    test('matching is case-insensitive', () {
      expect(faVoicePresetsFor(modelId: 'GPT-4o-mini-TTS'), isNotEmpty);
      expect(faVoicePresetsFor(modelId: 'KOKORO'), hasLength(12));
    });

    test('no match returns an empty list', () {
      expect(faVoicePresetsFor(modelId: 'gpt-4o'), isEmpty);
      expect(
