/// A quota adapter that counts its fetches (the probe contract).
class _CountingQuotaAdapter implements QuotaAdapter {
  var fetches = 0;

  @override
  Future<QuotaFetchResult> fetch() async {
    fetches++;
    return const QuotaFetchResult.unknown('probe');
  }
}

